import { App } from "aws-cdk-lib";
import { stringify } from "yaml";
import { GithubOidcStack } from "./github-oidc-stack.ts";

const HEADER = `# ShapesOS — GitHub Actions OIDC roles (standalone CloudFormation template).
# GENERATED by infra/aws (npm run bootstrap-template) from lib/github-oidc-stack.ts;
# do not edit by hand. Deploy once, from AWS CloudShell, before \`cdk bootstrap\`:
#   aws cloudformation deploy --template-file bootstrap.yaml \\
#     --stack-name shapesos-github-oidc --capabilities CAPABILITY_NAMED_IAM
# (add --parameter-overrides ExistingOidcProviderArn=<arn> if the account
# already has the token.actions.githubusercontent.com provider).
# Full steps: docs/deploy/AWS.md.
`;

export function bootstrapTemplate(repo = "Villain336/ShapesOS", environment = "production"): Record<string, unknown> {
  // No aws:cdk:path metadata: the template is read and pasted by a person.
  const app = new App({ context: { "aws:cdk:enable-path-metadata": false } });
  const stack = new GithubOidcStack(app, "ShapesOS-GithubOidc", { githubRepo: repo, githubEnvironment: environment });
  const template = app.synth().getStackByName(stack.stackName).template as Record<string, unknown>;
  return template;
}

export function bootstrapTemplateYaml(): string {
  return HEADER + stringify(bootstrapTemplate(), { lineWidth: 0 });
}
